let blocks = msg.payload;

// Guard clause to ensure all network blocks arrived safely
if (!blocks.vbr_status_block || !blocks.power_temp_block ||
    !blocks.control_metrics_block || !blocks.vib_extended_block) return null;

// ---------------------------------------------------------------
// HELPER: Modbus registers arrive as UNSIGNED 16-bit (0..65535).
// Sensor values that can legitimately be negative (acceleration,
// chip temperature below 0 degC) are 16-bit SIGNED and must be
// re-interpreted, or -0.5g would read as +65535-ish garbage.
// ---------------------------------------------------------------
function toSigned16(v) {
    return v > 32767 ? v - 65536 : v;
}

function safe(v) {
    return (typeof v === "number" && isFinite(v)) ? v : 0;
}

// 1. D210 Motor Status (block now contains only this single register)
let statusCode = blocks.vbr_status_block[0];

// 2. D222 Range parsing (Indices relative to start address 222)
let voltage = blocks.power_temp_block[0];
let amp = blocks.power_temp_block[1] / 100;
let power = blocks.power_temp_block[2] / 10;
let torque = blocks.power_temp_block[3] / 10;
let temperature = blocks.power_temp_block[8];

// 3. D4110 High-Range parsing (Parsing REALs/Floats from registers)
function parse32BitFloatSwapped(reg1, reg2) {
    let buffer = new ArrayBuffer(4);
    let view = new DataView(buffer);
    view.setUint16(0, reg2, false);
    view.setUint16(2, reg1, false);
    let result = view.getFloat32(0, false);
    return isNaN(result) ? 0 : result;
}

let frequency = parse32BitFloatSwapped(blocks.control_metrics_block[0], blocks.control_metrics_block[1]);
let rpm = parse32BitFloatSwapped(blocks.control_metrics_block[2], blocks.control_metrics_block[3]);

// 4. Calculate Speed Command and apply industrial state safety override
let speed_hz = blocks.control_metrics_block[102] / 200; // D4212 raw mapping

// CRITICAL FIX: If motor is E-STOP (0) or STOPPED (1), force target speed command to 0 Hz
if (statusCode === 0 || statusCode === 1) {
    speed_hz = 0;
}

// ---------------------------------------------------------------
// 5. D400 Range: EXTENDED VIBRATION BLOCK (new)
//    PLC COM0 reads ONE 22-register block: sensor addr 52 (0x34)
//    through 73 (0x49) -> D400..D421. Offsets below are relative
//    to D400 = index 0 = sensor register 0x34. Reserved gaps are
//    read but discarded (0x37-0x39, 0x3D-0x3F).
//
//    KNOWN LIMITATION (confirmed by controlled substitution test):
//    AX/AY/AZ (offsets 0-2) read back as hard 0x0000 on this sensor
//    unit regardless of PLC row/mapping. Velocity/temp/displacement/
//    frequency in the SAME transaction are all valid, so the
//    accelerometer itself is working (velocity is derived from it) -
//    this looks like a firmware limitation on the raw-acceleration
//    passthrough register specifically, not a dead sensor. Kept in
//    the payload (as 0) rather than removed, so it's visible in
//    Grafana as "not yet resolved" rather than silently missing.
// ---------------------------------------------------------------
let vibExt = blocks.vib_extended_block;

// Vibration velocity, now sourced HERE (offsets 6-8 = D406-408 =
// sensor reg 0x3A-0x3C = VX,VY,VZ), matching the PLC variable table's
// Motor_VBR_VX/VY/VZ. Same scaling as before: raw / 100 -> mm/s.
let vbr_x = vibExt[6] / 100;
let vbr_y = vibExt[7] / 100;
let vbr_z = vibExt[8] / 100;

// Acceleration: A = signed_raw / 32768 * 16   [g]   (offsets 0-2)
// Signed, because a real accelerometer swings both directions.
let accel_x = toSigned16(vibExt[0]) / 32768 * 16;
let accel_y = toSigned16(vibExt[1]) / 32768 * 16;
let accel_z = toSigned16(vibExt[2]) / 32768 * 16;

// offsets 3-5 = reserved (0x37-0x39), discarded
// offsets 6-8 = VX,VY,VZ (0x3A-0x3C) - duplicate of D200-202, not used here
// offsets 9-11 = reserved (0x3D-0x3F), discarded

// Sensor's own chip temperature = signed_raw / 100   [degC]  (offset 12)
// NB: this is the SENSOR chip, NOT the motor. Motor temp is `temperature`
// above (D230). Named distinctly on purpose so the two never get confused.
let sensor_chip_temp = toSigned16(vibExt[12]) / 100;

// Vibration displacement: raw value is already in micrometres [um]  (13-15)
let disp_x = vibExt[13];
let disp_y = vibExt[14];
let disp_z = vibExt[15];

// Dominant vibration frequency = raw / 10   [Hz]  (offsets 16-18)
let vib_freq_x = vibExt[16] / 10;
let vib_freq_y = vibExt[17] / 10;
let vib_freq_z = vibExt[18] / 10;

// Per-axis fault diagnosis codes, raw from the sensor  (offsets 19-21 =
// D419-D421). Reported as-is: these are status/diagnosis codes, not a
// measurement, so they are never scaled or averaged.
let fault_x = vibExt[19];
let fault_y = vibExt[20];
let fault_z = vibExt[21];

// 6. Map Operational State Text Labels
let statusLabel = "UNKNOWN";
switch (statusCode) {
    case 0: statusLabel = "E-STOP"; break;
    case 1: statusLabel = "STOPPED"; break;
    case 2: statusLabel = "RUNNING"; break;
}

// 7. Build Shared Identity Metadata
// The machine this flow is polling. It MUST match the Machine ID
// registered in the dashboard — that string is what links these
// readings to the right machine everywhere downstream.
let machineId = "motor01";
let identityTags = { asset_id: machineId };

// ==========================================
// OUTPUT MESSAGE 1: Tailored for InfluxDB Out
// ==========================================
let msgInflux = {
    payload: [
        {
        vibration_x: safe(vbr_x),
        vibration_y: safe(vbr_y),
        vibration_z: safe(vbr_z),
        temperature: safe(temperature),
        current: safe(amp),
        torque: safe(torque),
        speed_command_hz: safe(speed_hz), // Safely drops to 0 on stop
        frequency: frequency,
        rpm: rpm,
        voltage: safe(voltage),
        power: safe(power),
        status_code: statusCode,

        // --- new extended vibration fields ---
        accel_x: safe(accel_x),
        accel_y: safe(accel_y),
        accel_z: safe(accel_z),
        sensor_chip_temp: safe(sensor_chip_temp),
        disp_x: safe(disp_x),
        disp_y: safe(disp_y),
        disp_z: safe(disp_z),
        vib_freq_x: safe(vib_freq_x),
        vib_freq_y: safe(vib_freq_y),
        vib_freq_z: safe(vib_freq_z),
        fault_x: safe(fault_x),
        fault_y: safe(fault_y),
        fault_z: safe(fault_z)
    },
        { machine_id: machineId }
    ]
};

// Clean out measurement property properties to keep Grafana rows clear
delete msgInflux.measurement;

// ==========================================
// OUTPUT MESSAGE 2: Tailored for Postgres Pipeline
// ==========================================
let msgPostgres = {
    payload: {
        status_code: statusCode,
        status_label: statusLabel
    },
    tags: identityTags
};

return [msgInflux, msgPostgres];

let statusData = msg.payload;
let tagsData = msg.tags;

// Assign the raw SQL string statement directly to msg.query
msg.query = `INSERT INTO machine_activity_logs (asset_id, status_code, status_label) 
             VALUES ('${tagsData.asset_id}', ${statusData.status_code}, '${statusData.status_label}');`;

return msg;

// ---------------------------------------------------------------------------
// Build the MQTT payload defined in the Node-RED MQTT Publishing Guideline
// v1.0, section 6.1.
//
// Fed from the InfluxDB output of "Map, Scale & Process Buffer", so this branch
// publishes without altering anything already working. That message carries
// payload = [fields, tags]. A brand new message object is returned rather than
// mutating msg, so the InfluxDB write on the same output is never affected.
// ---------------------------------------------------------------------------

// --- Identity (guideline sections 5 and 6.1) -------------------------------
const SITE_ID = "SITE001";
const DEVICE_TYPE = "MOTOR";
const DEVICE_ID = "MOTOR001";

// --- Integer scaling -------------------------------------------------------
// The guideline types every measurement as INTEGER, so each value is
// multiplied by the factor below and rounded. Consumers divide by the same
// factor to recover engineering units.
//
// The factors match the precision the sensor actually reports, which means the
// transmitted integer is generally the raw Modbus register value again -
// nothing is invented and nothing is lost. Acceleration is the exception: it
// is derived from a +/-16 g full-scale word, so it is sent in milli-g.
const SCALE = {
    motor_status: 1,             // state code 0/1/2
    motor_frequency: 100,        //  49.97 Hz   -> 4997
    motor_RPM: 10,               // 1452.4 rpm  -> 14524
    motor_temperature: 1,        // whole degC from the PLC
    invt_bus_volt: 1,
    motor_volt: 1,               // whole volts from the PLC
    motor_amp: 100,              //   4.48 A    -> 448
    motor_power: 10,             //   2.2 kW    -> 22
    motor_torque: 10,            //  14.3 %     -> 143
    motor_VBR_chiptemp: 100,     //  31.5 degC  -> 3150
    motor_VBR_V: 100,            //   1.24 mm/s -> 124
    motor_VBR_A: 1000,           //   0.012 g   -> 12   (milli-g)
    motor_VBR_D: 1,              // already whole micrometres
    motor_VBR_F: 10,             //  24.6 Hz    -> 246
    motor_VBR_fault: 1           // diagnosis code, never scaled
};

// Fields the current Modbus blocks do not read are published as null rather
// than 0, so a consumer can tell "not measured" from "measured as zero".
const UNAVAILABLE = null;

const fields = Array.isArray(msg.payload) ? msg.payload[0] : msg.payload;
if (!fields) { return null; }

// "2026-09-03 15:06:20" - YYYY-MM-DD HH:mm:ss, per the section 6.1 spec.
function formatDts(d) {
    const p = (n) => String(n).padStart(2, "0");
    return d.getFullYear() + "-" + p(d.getMonth() + 1) + "-" + p(d.getDate()) +
        " " + p(d.getHours()) + ":" + p(d.getMinutes()) + ":" + p(d.getSeconds());
}

function scaled(v, factor) {
    if (v === null || v === undefined || typeof v !== "number" || !isFinite(v)) {
        return null;
    }
    return Math.round(v * factor);
}

const body = {
    site_id: SITE_ID,
    device_type: DEVICE_TYPE,
    device_id: DEVICE_ID,
    dts: formatDts(new Date()),
    data: {
        motor_status: scaled(fields.status_code, SCALE.motor_status),
        motor_frequency: scaled(fields.frequency, SCALE.motor_frequency),
        motor_RPM: scaled(fields.rpm, SCALE.motor_RPM),
        motor_temperature: scaled(fields.temperature, SCALE.motor_temperature),

        // Not read by the current register blocks - needs the VFD DC bus
        // voltage register adding to the Modbus reads.
        invt_bus_volt: UNAVAILABLE,

        motor_volt: scaled(fields.voltage, SCALE.motor_volt),
        motor_amp: scaled(fields.current, SCALE.motor_amp),
        motor_power: scaled(fields.power, SCALE.motor_power),
        motor_torque: scaled(fields.torque, SCALE.motor_torque),
        motor_VBR_chiptemp: scaled(fields.sensor_chip_temp, SCALE.motor_VBR_chiptemp),

        motor_VBR_VX: scaled(fields.vibration_x, SCALE.motor_VBR_V),
        motor_VBR_VY: scaled(fields.vibration_y, SCALE.motor_VBR_V),
        motor_VBR_VZ: scaled(fields.vibration_z, SCALE.motor_VBR_V),

        // D400-D402. These have historically read hard zero on this
        // WTVB01-485 unit; the value is published as measured either way.
        motor_VBR_AX: scaled(fields.accel_x, SCALE.motor_VBR_A),
        motor_VBR_AY: scaled(fields.accel_y, SCALE.motor_VBR_A),
        motor_VBR_AZ: scaled(fields.accel_z, SCALE.motor_VBR_A),

        motor_VBR_DX: scaled(fields.disp_x, SCALE.motor_VBR_D),
        motor_VBR_DY: scaled(fields.disp_y, SCALE.motor_VBR_D),
        motor_VBR_DZ: scaled(fields.disp_z, SCALE.motor_VBR_D),

        motor_VBR_FX: scaled(fields.vib_freq_x, SCALE.motor_VBR_F),
        motor_VBR_FY: scaled(fields.vib_freq_y, SCALE.motor_VBR_F),
        motor_VBR_FZ: scaled(fields.vib_freq_z, SCALE.motor_VBR_F),

        // D419-D421, per-axis fault diagnosis codes.
        motor_VBR_faultX: scaled(fields.fault_x, SCALE.motor_VBR_fault),
        motor_VBR_faultY: scaled(fields.fault_y, SCALE.motor_VBR_fault),
        motor_VBR_faultZ: scaled(fields.fault_z, SCALE.motor_VBR_fault)
    }
};

return {
    topic: "pmm/" + SITE_ID + "/" + DEVICE_ID,
    payload: JSON.stringify(body),
    qos: 1,
    retain: false
};
